-- Rich First Vision: store the member's own words per category during the
-- /begin Draft Session, and keep the per-category starter / imagination /
-- vision text the compose pass produces. Additive.
-- NOTE: supabase/COMPLETE_SCHEMA_DUMP.sql is regenerated by the user after apply.

-- 1. Notes carry the verbatim member passage. `text` stays the short label.
ALTER TABLE public.vision_draft_session_notes
  ADD COLUMN IF NOT EXISTS member_text text;

ALTER TABLE public.vision_draft_session_notes
  DROP CONSTRAINT IF EXISTS vision_draft_session_notes_source_check;
ALTER TABLE public.vision_draft_session_notes
  ADD CONSTRAINT vision_draft_session_notes_source_check
  CHECK (source = ANY (ARRAY['activation', 'viva', 'member']));

-- "I don't know yet" is a valid answer; it clears the depth gate without text.
ALTER TABLE public.vision_draft_session_notes
  DROP CONSTRAINT IF EXISTS vision_draft_session_notes_polarity_check;
ALTER TABLE public.vision_draft_session_notes
  ADD CONSTRAINT vision_draft_session_notes_polarity_check
  CHECK (polarity = ANY (ARRAY['contrast', 'clarity', 'unknown']));

-- 2. Per-category compose artifacts (starter, member imagination, written vision).
CREATE TABLE IF NOT EXISTS public.vision_draft_session_category_text (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES public.vision_draft_sessions (id) ON DELETE CASCADE,
  category text NOT NULL
    CHECK (category = ANY (ARRAY[
      'fun', 'health', 'travel', 'love', 'family', 'social',
      'home', 'work', 'money', 'stuff', 'giving', 'spirituality'
    ])),
  starter_text text,
  imagination_text text,
  vision_text text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (session_id, category)
);

CREATE INDEX IF NOT EXISTS idx_vision_draft_session_category_text_session
  ON public.vision_draft_session_category_text (session_id);

DROP TRIGGER IF EXISTS vision_draft_session_category_text_set_updated_at
  ON public.vision_draft_session_category_text;
CREATE TRIGGER vision_draft_session_category_text_set_updated_at
  BEFORE UPDATE ON public.vision_draft_session_category_text
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.vision_draft_session_category_text ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "vision_draft_session_category_text_owner_select"
  ON public.vision_draft_session_category_text;
CREATE POLICY "vision_draft_session_category_text_owner_select"
  ON public.vision_draft_session_category_text FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_category_text_owner_insert"
  ON public.vision_draft_session_category_text;
CREATE POLICY "vision_draft_session_category_text_owner_insert"
  ON public.vision_draft_session_category_text FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_category_text_owner_update"
  ON public.vision_draft_session_category_text;
CREATE POLICY "vision_draft_session_category_text_owner_update"
  ON public.vision_draft_session_category_text FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_category_text_owner_delete"
  ON public.vision_draft_session_category_text;
CREATE POLICY "vision_draft_session_category_text_owner_delete"
  ON public.vision_draft_session_category_text FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_category_text_service_all"
  ON public.vision_draft_session_category_text;
CREATE POLICY "vision_draft_session_category_text_service_all"
  ON public.vision_draft_session_category_text FOR ALL
  USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');

ALTER PUBLICATION supabase_realtime ADD TABLE public.vision_draft_session_category_text;
